import * as React from "react";
import { useState, useRef } from "react";
import "./TopNav.scss";
import TopNavItem from "./TopNavItem";
import TopNavRightItem from "./TopNavRightItem";
import SearchBar from "./SearchBar";
import MenuBlock from "../menuBlock/MenuBlock";
import ColumnsNavigation from "../columnsNavigation/ColumnsNavigation";
import NormalTextLink from "../normalTextLink/NormalTextLink";
import Button from "../button/Button";
import IconButton from "../iconButton/IconButton";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon, SvgMpaLogo } from "../../assets/icons";
import { MpaLogo } from "../logo/MpaLogo";
import { Avatar } from "../avatar";
import { Link as RouterLink } from "react-router-dom"


export interface NavMenuItem {
  label: string;
  leadingIcon?: keyof typeof SvgMpaIcon | string;
  showDivider?: boolean;
  disabled?: boolean;
  subMenuItems?: NavMenuItem[];
};

export interface TopNavProps {

  /**
   * Unique identifier for the topnav
   */
  id: string,

  /** Array of navigation items */
  navItems: {
    label: string;
    header?: string;
    desc?: string,
    link?: string,
    menuItems: {
      label: string;
      leadingIcon?: keyof typeof SvgMpaIcon | string;
      showDivider?: boolean;
      disabled?: boolean;
      subMenuItems?: NavMenuItem[];
    }[];
  }[];

  /** Logo icon name or path */
  logo?: keyof typeof SvgMpaLogo | string;

  /** Optional colour theme for buttons/icons */
  colour?: "primary" | "secondary" | "tertiary";

  /** Layout type */
  layout?: "menu-block" | "mega-menu" | "mega-menu-2";

  /** Toggle for showing the search bar */
  showSearch?: string | boolean;

  /** Toggle for showing login button */
  showLogin?: boolean;

  /** Optional class name for the top nav */
  className?: string;

  /** Toggle for showing avatar */
  showAvatar?: boolean;

  /*Optional header text */
  headerText?: string;

  logoUrl?: string;

  headerNavItems?: {
    label: string;
    link?: string;
    iconName?: keyof typeof SvgMpaIcon | string;

  }[];

  /* Pass your own Router Link from application */
  LinkComponent?: React.ComponentType<any>;

  /* Optional indicator for if the nav bar is 1-level deep */
  isSingleLevel?: boolean;

}


const TopNav: React.FC<TopNavProps> = ({
  id,
  navItems,
  logo = "MpaWhiteLogo",
  colour = "primary",
  layout,
  showSearch = "true",
  showLogin = "true",
  showAvatar = false,
  className,
  headerText,
  logoUrl,
  headerNavItems,
  LinkComponent,
  isSingleLevel = false
}) => {
  const Link = LinkComponent ?? RouterLink;

  const [openIndex, setOpenIndex] = React.useState<number | null>(null);

  const [isSearchVisible, setSearchVisible] = useState(false);

  const searchInputRef = useRef<HTMLInputElement>(null);

  const handleToggleMenu = (index: number) => {
    if (openIndex === index) {
      setOpenIndex(null);
    } else {
      setOpenIndex(index);
      setOpenItem(0);
    }
  };

  const [openItem, setOpenItem] = useState<number | null>(0);

  const handleHeaderClick = (index: number) => {
    setOpenItem(openItem === index ? 0 : index);
  };


  const renderIcon = () => {
    return isSearchVisible ? "X" : "Search";
  };


  const showSearchBar = () => {
    setSearchVisible(!isSearchVisible);

    if (!isSearchVisible) {
      setOpenIndex(null); // Close the menu when the search bar is shown
    }

    // Focus on the input when search bar is shown
    if (!isSearchVisible && searchInputRef.current) {
      searchInputRef.current.focus();
    }
  };

  const searchBoxClass = `${isSearchVisible ? 'show' : 'hide'}`;
  const [isUserMenuOpen, setUserMenuOpen] = useState(false);

  const toggleUserMenu = (e: React.MouseEvent) => {
    if (!isSingleLevel) {
      e.stopPropagation(); // prevent parent clicks
      setUserMenuOpen(prev => !prev);
    }
  };

  return (
    <>
      <div id={id} className="top-nav-container">

        {/* <TopItemBlock navItems={navItems} layout={layout} colour={colour}/> */}

        <div className={`main-top-nav ${className}`}>
          {logoUrl ? (<a href={logoUrl}><div className="logo-container">
            {logo && (<MpaLogo logoName={logo} width={60} height={60} />)}
          </div>
          </a>) : (<div className="logo-container">
            {logo && (<MpaLogo logoName={logo} width={60} height={60} />)}
          </div>)}

          <div className={`top-nav ${colour} ${className} `}>
            {isSingleLevel
              ? <div className="nav-item-container-single">
                  {navItems.map((item, index) => (
                    <div key={index} className="nav-item-content-single">
                      {item.link ? (
                        <Link
                          id={`nav-item-${index}`}
                          className="nav-item-single"
                          to={item.link}
                        >
                          {item.label}
                        </Link>
                      ) : (
                        <div>{item.label}</div>
                      )}
                    </div>
                  ))}
              </div>
              : <>
                {navItems.map((navItem, index) => (
                  <div key={index} className="nav-item-container">
                    <div className={`top-nav-item ${openIndex === index && searchBoxClass === 'hide' ? 'open' : ''}`}>
                      {(navItem.link && (navItem.menuItems === undefined || navItem.menuItems.length === 0))
                        // for single-level menu items 
                        ? <Link className="nav-item-content" to={navItem.link}> 
                            <span className="name">{navItem.label}</span>
                          </Link>
                        // for multi-level menu items
                        : <div className="nav-item-content" onClick={() => handleToggleMenu(index)}>
                            <TopNavItem navItem={navItem} index={index} openIndex={openIndex} />
                          </div>
                      }
                    </div>

                    {layout == "menu-block" && (
                      navItem.menuItems && openIndex === index && searchBoxClass === 'hide' && (
                        <div className="menu-block-item">
                          <MenuBlock id="menuBlockId" menuItems={navItem.menuItems} colour={colour} />
                        </div>
                      )
                    )}
                  </div>
                ))}
              </>
            }
          </div>

          <div className={`header-action ${className}`}>
            <div className={`auth-container ${className}`}>
              {showAvatar && (<Avatar
                id={"avatarId"}
                size="small"
                type="icon"
                icon="User_Filled"
                showMenuBlock={false}
              />)}
              {headerText && (
                <div className="header-text">
                  {headerText}
                </div>
              )}

              {headerText && (
                <span
                  className="chevron-toggle"
                  onClick={toggleUserMenu}
                  role="button"
                  aria-expanded={isUserMenuOpen}
                >
                  <MpaIcon iconName={isUserMenuOpen ? "ChevronUp" : "ChevronDown"} />
                </span>
              )}

              {isUserMenuOpen && headerNavItems?.length && (
                <div className="user-dropdown-menu">
                  <ul className="header-dropdown-list">
                    {headerNavItems.map((item, index) => (
                      <li key={index} className="header-dropdown-item">
                        {item.link ? (
                          <a
                            href={item.link}
                            onClick={() => setUserMenuOpen(false)}
                          >
                            {item.iconName && <MpaIcon iconName={item.iconName} size={20} />} {item.label}
                          </a>
                        ) : (
                          <span>{item.iconName && <MpaIcon iconName={item.iconName} size={20} />}{item.label}</span>
                        )}
                      </li>
                    ))}
                  </ul>
                </div>
              )}


              {showLogin && (
                <Button id={"buttonId"} leadingIcon={"Lock"} label="Login"></Button>
              )}

            </div>

            <div className="search-container">
              {showSearch && (
                <IconButton
                  id="iconButtonId"
                  className={`icon-btn icon-btn-square icon-btn-${colour}`}
                  icon={renderIcon()}
                  btnType={"standard"}
                  onClick={showSearchBar}
                >
                </IconButton>
              )}
            </div>
          </div>
        </div>

        {navItems.map((navItem, index) => {
          return (
            navItem.menuItems && openIndex === index && searchBoxClass === 'hide' && (
              <React.Fragment key={index}>
                {layout == "mega-menu" && (
                  <div className="columns-nav-item" key={index}>
                    <div className="columns-nav-block">
                      <TopNavRightItem navItem={navItem} layout={layout} index={index} />
                      <div className="columns-nav-content"><ColumnsNavigation id="columnNavigationId" menuItems={navItem.menuItems} /></div>
                    </div>
                  </div>
                )}

                {layout == "mega-menu-2" && (
                  <>
                    <div className="menu-name"><span>{navItem?.label}</span></div>
                    <div>
                      {navItem?.menuItems.map((section, index) => (

                        <div className="second-mega-container" key={index}
                        >
                          {/* TopNavRightItem */}
                          <div className={`second-header ${openItem === index ? 'selected' : ''}`}>
                            {section?.label && <NormalTextLink id={"normalLinkId"} href={navItem?.link}><h3 className="column-header" onClick={() => handleHeaderClick(index)}>{section.label}</h3></NormalTextLink>}
                            {section?.subMenuItems &&
                              <span>
                                <MpaIcon iconName={'ChevronRight'} />
                              </span>}
                          </div>

                          {/* <TopNavRightItem navItem={section} layout={layout} openItem={openItem} index={index} hasSubMenu={section?.subMenuItems && section.subMenuItems.length > 0 ? true : false}/> */}

                          <div className="columns-nav-content absolute">
                            <ColumnsNavigation id={"columnNavigationId"} menuItems={section.subMenuItems ?? []} />
                          </div>
                        </div>
                      ))}
                    </div>
                  </>
                )}

              </React.Fragment>
            )
          );
        })}
      </div>


      {/* Search Container  */}
      {/* <div>    */}
      <SearchBar className={`search-box ${searchBoxClass}`} buttonClassName={`icon-btn icon-btn-square icon-btn-${colour}`} />
      {/* </div> */}

    </>
  );
};

export default TopNav;
